const lead = $node["Merge AI Results"].json.finalRecord;
const tier = lead.classification;

// A small set of examples keeps the three lead tiers demonstrably distinct.
const examples = {
  HOT: "Subject: Let’s plan your renovation consultation\nBody: Hi Jordan, thanks for the detailed kitchen project. With your $75k–$150k budget and ASAP timeline, we can help you map the next steps. Reply with two convenient times this week for a consultation.",
  WARM: "Subject: Your renovation project\nBody: Hi Jordan, thanks for sharing your bathroom renovation plans. We’d be happy to answer questions and discuss options when your timing is right.",
  COLD: "Subject: Ideas for your future renovation\nBody: Hi Jordan, thanks for telling us about your project. We’re here when you’re ready, and can share practical planning guidance in the meantime.",
};

const prompt = `You write concise, professional follow-up emails for a home renovation company. Return ONLY JSON: {"subject": string, "html": string}. Use the lead’s actual details; never invent details. Do not mention lead scoring or classifications. Use a warm, specific tone and simple HTML paragraphs.\n\nTier: ${tier}\nTone example: ${examples[tier]}\n\nLead: ${JSON.stringify({name: lead.name, projectType: lead.project_type, budget: lead.budget, location: lead.location, timeline: lead.timeline, description: lead.description})}`;
return [{json: {lead, emailPrompt: prompt}}];

const response = $input.item.json;
const lead = $node["Prepare Personalized Email"].json.lead;
try {
  const body = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
  const text = body?.candidates?.[0]?.content?.parts?.[0]?.text;
  const email = JSON.parse(text);
  if (!email.subject || !email.html) throw new Error('Invalid email JSON');
  return [{json: {subject: email.subject, html: email.html, lead}}];
} catch (error) {
  // Keep the original lead workflow alive even if copy generation fails.
  return [{json: {subject: `Your ${lead.project_type} project`, html: `<p>Hi ${lead.name},</p><p>Thank you for contacting RenovateAI. Our team will be in touch shortly.</p>`, lead, generationError: error.message}}];
}

const item = $input.item.json;

return [
  {
    json: {
      statusCode: 400,
      response: {
        ok: false,
        message: "Payload validation failed",
        errors: item.validationErrors,
      },
    },
  },
];
